// SQ-01 pure browser-display/request oracle. No network, storage or tariff claim.
// Private addresses and monetary response values remain caller-owned in memory.
const identity = require('./authenticated-session-contract.cjs');

const addressKeys = Object.freeze(['recipient_name', 'recipient_mobile', 'province',
  'province_code', 'city', 'city_code', 'postal_code', 'address_line']);

function fail(code) {
  throw Object.assign(new Error(code), { code }); // Never interpolate private values.
}

function completeIntendedAddress(address) {
  if (!identity.exactKeys(address, addressKeys)) return false;
  for (const key of ['recipient_name', 'recipient_mobile', 'province', 'city',
    'postal_code', 'address_line']) {
    if (typeof address[key] !== 'string') return false;
  }
  // Current public client predicate plus the user's explicit Tehran/Narmak intent.
  // This verifies input identity/completeness, not deliverability or provider safety.
  const district = address.address_line.normalize('NFKC').replace(/ك/g, 'ک').toLowerCase();
  return address.recipient_name.trim().split(/\s+/).filter(Boolean).length >= 2 &&
    /^09[0-9]{9}$/.test(address.recipient_mobile) &&
    address.province_code === 1 && address.city_code === 1 &&
    address.province === 'تهران' && address.city === 'تهران' &&
    /^[0-9]{10}$/.test(address.postal_code) &&
    Array.from(address.address_line.trim()).length >= 10 &&
    /(?:^|[^\p{L}\p{N}])(?:نارمک|narmak)(?=$|[^\p{L}\p{N}])/u.test(district);
}

// Body is the actual observed {address} contract. Both address objects must have
// exactly the observed eight fields; comparison includes recipient and postal.
function matchesAddress(body, formAddress) {
  return identity.exactKeys(body, ['address']) &&
    completeIntendedAddress(body.address) && completeIntendedAddress(formAddress) &&
    addressKeys.every(key => body.address[key] === formAddress[key]);
}

// Local to one run; caller must also reserve the run in Node before checkout so
// rerunning/reloading a spec cannot grant a fresh real-request allowance.
function createQuoteBudget() {
  let consumed = false;
  return Object.freeze({
    permit() {
      if (consumed) fail('SHIPPING_QUOTE_BUDGET_EXHAUSTED');
      consumed = true; // Consume BEFORE transport, even if transport later fails.
      return 1;
    },
    snapshot() { return { consumed, count: consumed ? 1 : 0, limit: 1 }; }
  });
}

function validQuoteResponse(response) {
  return Boolean(response && typeof response === 'object' && !Array.isArray(response) &&
    ['shipping_irr', 'total_irr'].every(key => Object.hasOwn(response, key) &&
      numericAmount(response[key]) !== null));
}

function numericAmount(value) {
  // Match the public formatter's Number(value), but reject the missing/blank or
  // nonnumeric primitives it would silently turn into zero. Shipping's backend
  // integer/sign policy is not established and is outside this display claim.
  if (typeof value !== 'number' && typeof value !== 'string') return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  const amount = Number(value);
  return Number.isFinite(amount) ? amount : null;
}

function normalizedRial(value) {
  if (typeof value !== 'string') return null;
  const normalized = identity.displayDigits(value).replace(/٬/g, ',').replace(/٫/g, '.')
    .replace(/−/g, '-').replace(/[\s\u061c\u200e\u200f\u202a-\u202e\u2066-\u2069]/g, '');
  if (!/^-?(?:[0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)(?:\.[0-9]+)?ریال$/.test(normalized)) return null;
  return normalized;
}

// Fresh request/response correlation and unchanged exact cart are independent
// guard/spec prerequisites. This function cannot prove freshness from text alone.
// No comparison with subtotal or independent pricing formula belongs here.
function assertDisplay(observation) {
  if (!observation || typeof observation !== 'object' || Array.isArray(observation)) {
    fail('SHIPPING_QUOTE_OBSERVATION_INVALID');
  }
  const { response, shippingText, totalText, quoted, loading, fallbackNotePresent } = observation;
  if (!validQuoteResponse(response)) fail('SHIPPING_QUOTE_RESPONSE_INVALID');
  if (quoted !== true) fail('SHIPPING_QUOTE_RENDER_NOT_QUOTED');
  if (loading !== false) fail('SHIPPING_QUOTE_RENDER_STILL_LOADING');
  if (fallbackNotePresent !== false) fail('SHIPPING_QUOTE_SUBTOTAL_FALLBACK_PRESENT');
  const actualShipping = normalizedRial(shippingText);
  const actualTotal = normalizedRial(totalText);
  if (actualShipping === null) fail('SHIPPING_QUOTE_FEE_CURRENCY_OR_FORMAT_INVALID');
  if (actualTotal === null) fail('SHIPPING_QUOTE_TOTAL_CURRENCY_OR_FORMAT_INVALID');
  // Independent construction of the documented display mapping, not an oracle
  // for price or rounding policy. Intl defaults include at most three decimals.
  const formatter = new Intl.NumberFormat('fa-IR');
  const expected = value => normalizedRial(formatter.format(numericAmount(value)) + ' ریال');
  if (actualShipping !== expected(response.shipping_irr)) fail('SHIPPING_QUOTE_FEE_DISPLAY_MISMATCH');
  if (actualTotal !== expected(response.total_irr)) fail('SHIPPING_QUOTE_TOTAL_DISPLAY_MISMATCH');
  return true;
}

module.exports = { createQuoteBudget, matchesAddress, validQuoteResponse, assertDisplay };
